values.content:
=You help a freelancer triage Upwork job emails.
Freelancer profile: {{ $json.profile }}
Write all explanations in {{ $json.language }}.
Find every job in the email. Score each 0-10 for this freelancer: reward clear small scope, verified payment, few proposals, matching skills; heavily penalize Expert/Senior roles, required niche track record, off-stack technology, 20+ proposals and red flags (work outside Upwork, upfront payment).
Never copy long tracking links. url only if it is https://www.upwork.com/jobs/~...
Return only JSON: {"jobs": [{"title": "", "url": "", "budget": "", "summary": "", "why": "", "risks": "", "score": 0}]}

parameters.jsCode:
// One item per job; the 'View job details' link is taken from the email as-is
const out = [];
$input.all().forEach((item, i) => {
  const src = $('Your profile & settings').itemMatching(i).json;
  let raw = item.json.text;
  if (raw === undefined) for (const o of (item.json.output || [])) for (const c of (o.content || [])) if (c.text !== undefined) raw = c.text;
  let data;
  try { data = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return; }
  const jobs = (data && Array.isArray(data.jobs)) ? data.jobs : [];
  const links = [...String(src.text || '').matchAll(/View job details\s*\(\s*(https?:\/\/[^\s)]+)\s*\)/gi)].map((m) => m[1]);
  jobs.forEach((job, k) => {
    const score = Math.max(0, Math.min(10, Math.round(Number(job.score) || 0)));
    if (score < Number(src.min_score || 6)) return;
    const direct = /^https:\/\/www\.upwork\.com\/jobs\/~/.test(job.url || '') ? job.url : '';
    const link = direct || (links.length === jobs.length ? links[k] : (jobs.length === 1 ? links[0] : '')) || 'https://www.upwork.com/nx/search/jobs/?q=' + encodeURIComponent(String(job.title || '').slice(0, 120));
    out.push({ json: { ...job, score, link } });
  });
});
return out;

// HTML card for Telegram
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const j = $json;
const card = [
  (j.score >= 8 ? '\uD83D\uDD25 ' : '\uD83C\uDD95 ') + '<b>' + esc(j.title) + '</b>  ' + j.score + '/10',
  j.budget ? '\uD83D\uDCB0 ' + esc(j.budget) : '',
  '\uD83D\uDCDD ' + esc(j.summary),
  '\u2705 ' + esc(j.why) + (j.risks ? '\n\u26A0\uFE0F ' + esc(j.risks) : ''),
].filter(Boolean).join('\n\n').slice(0, 4000);
return { json: { ...j, card } };
